/**
 * Vinta School OS — Student Drawer
 * Slide-in panel from the right showing student details,
 * guardians, payment plan, and contact actions.
 */

import { useCallback, useEffect, useRef, useState } from 'react'
import {
  X,
  Phone,
  MessageCircle,
  User,
  Shield,
  BookOpen,
  CreditCard,
  Plus,
  Tag,
  Edit3,
  Save,
  ChevronLeft,
} from 'lucide-react'
import { cn } from '../../lib/cn'
import api from '../../lib/api'
import { toast } from '../../stores/uiStore'
import {
  getInitials,
  formatPhone,
  getStatusColor,
  getStatusBg,
  formatCurrency,
} from '../../lib/formatters'
import type { Student } from '../../types/student'

// ============================================
// Props
// ============================================

export interface StudentDrawerProps {
  student: Student | null
  isOpen: boolean
  onClose: () => void
  onUpdated?: () => void
}

// ============================================
// Payment Preset type
// ============================================

interface PaymentPreset {
  id: string
  name: string
  amount: number
}

// ============================================
// Component
// ============================================

export default function StudentDrawer({ student, isOpen, onClose, onUpdated }: StudentDrawerProps) {
  const drawerRef = useRef<HTMLDivElement>(null)

  // Edit state
  const [isEditing, setIsEditing] = useState(false)
  const [editFirstName, setEditFirstName] = useState('')
  const [editLastName, setEditLastName] = useState('')
  const [editPhone, setEditPhone] = useState('')
  const [editParentPhone, setEditParentPhone] = useState('')
  const [editNotes, setEditNotes] = useState('')
  const [saving, setSaving] = useState(false)

  // Payment plan state
  const [paymentPresets, setPaymentPresets] = useState<PaymentPreset[]>([])
  const [billingRecords, setBillingRecords] = useState<Array<{ id: string; amount_da: number; status: string }>>([])
  const [showPaymentModal, setShowPaymentModal] = useState(false)

  // T9 billing summary: wired to real endpoints (Not set fallbacks, never silent)
  const [profile, setProfile] = useState<any>(null)
  const [subs, setSubs] = useState<Array<{
    id: string; group_id: string; group_name?: string | null; billing_model?: string;
    total_credits?: number | null; cycle_deadline?: string | null; status?: string;
  }>>([])
  const [profileError, setProfileError] = useState<string | null>(null)

  /* ── Fetch student billing records ── */
  const fetchBillingRecords = useCallback(async () => {
    if (!student) return
    try {
      const res = await api.get('/billing/students', { params: { student_id: student.id } })
      setBillingRecords(res.data.billings ?? [])
    } catch {
      // Silent — billing data is supplementary
    }
  }, [student])

  /* ── T9: profile (enrollments) + subscriptions for the billing summary ── */
  const fetchT9 = useCallback(async () => {
    if (!student) return
    setProfileError(null)
    try {
      const [pRes, sRes] = await Promise.all([
        api.get(`/students/${student.id}`).catch(() => null),
        api.get('/billing/subscriptions', { params: { student_id: student.id } }).catch(() => null),
      ])
      if (pRes?.data) setProfile(pRes.data)
      else setProfile(null)
      const list = sRes?.data?.subscriptions ?? sRes?.data ?? []
      setSubs(Array.isArray(list) ? list : [])
      if (!pRes?.data && !sRes?.data) setProfileError('Billing summary Not set.')
    } catch {
      setProfile(null)
      setSubs([])
      setProfileError('Billing summary Not set.')
    }
  }, [student])

  useEffect(() => {
    if (isOpen && student) {
      fetchBillingRecords()
      void fetchT9()
    }
  }, [isOpen, student, fetchBillingRecords, fetchT9])

  /* ── ESC key handler ── */
  useEffect(() => {
    if (!isOpen) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [isOpen, onClose])

  /* ── Body scroll lock ── */
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden'
    } else {
      document.body.style.overflow = ''
    }
    return () => {
      document.body.style.overflow = ''
    }
  }, [isOpen])

  /* ── Click outside handler ── */
  const handleBackdropClick = useCallback(
    (e: React.MouseEvent) => {
      if (e.target === e.currentTarget) onClose()
    },
    [onClose],
  )

  /* ── Edit handlers ── */
  const startEditing = useCallback(() => {
    if (!student) return
    setEditFirstName(student.first_name || '')
    setEditLastName(student.last_name || '')
    setEditPhone(student.phone || '')
    setEditParentPhone(student.parent_phone || '')
    setEditNotes(student.notes || '')
    setIsEditing(true)
  }, [student])

  const cancelEditing = useCallback(() => {
    setIsEditing(false)
  }, [])

  const saveEditing = useCallback(async () => {
    if (!student) return
    setSaving(true)
    try {
      await api.put(`/students/${student.id}`, {
        first_name: editFirstName.trim(),
        last_name: editLastName.trim(),
        phone: editPhone.trim() || null,
        parent_phone: editParentPhone.trim() || null,
        notes: editNotes.trim() || null,
      })
      toast.success('Student updated', 'Profile has been saved.')
      setIsEditing(false)
      onUpdated?.()
    } catch {
      toast.error('Update failed', 'Could not save changes. Please try again.')
    } finally {
      setSaving(false)
    }
  }, [student, editFirstName, editLastName, editPhone, editParentPhone, editNotes, onUpdated])

  if (!isOpen || !student) return null

  return (
    <div
      className="fixed inset-0 z-50 flex justify-end"
      onClick={handleBackdropClick}
    >
      {/* Backdrop */}
      <div className="absolute inset-0 bg-black/30 backdrop-blur-sm animate-fade-in" />

      {/* Drawer */}
      <div
        ref={drawerRef}
        className={cn(
          'relative h-full w-[400px] max-w-[90vw]',
          'bg-[var(--glass)] border-l border-[var(--glass-border)]',
          'backdrop-blur-xl shadow-2xl',
          'flex flex-col',
          'animate-slide-in-right',
        )}
        onClick={(e) => e.stopPropagation()}
      >
        {/* ── Header ──────────────────────────────── */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-[var(--glass-border)]">
          <div className="flex items-center gap-2">
            {isEditing ? (
              <button
                onClick={cancelEditing}
                className={cn(
                  'p-1.5 rounded-lg',
                  'hover:bg-[var(--glass)] text-[var(--muted)]',
                  'transition-colors duration-150',
                )}
              >
                <ChevronLeft size={16} />
              </button>
            ) : null}
            <h3
              className="text-base font-bold text-[var(--text)]"
              style={{ fontFamily: 'var(--font-heading)' }}
            >
              {isEditing ? 'Edit Profile' : 'Student Profile'}
            </h3>
          </div>
          <div className="flex items-center gap-1.5">
            {isEditing ? (
              <>
                <button
                  onClick={cancelEditing}
                  className={cn(
                    'px-3 py-1.5 rounded-lg text-xs font-medium',
                    'bg-[var(--input-bg)] text-[var(--muted)] border border-[var(--glass-border)]',
                    'hover:bg-[var(--glass)] transition-colors duration-150',
                  )}
                >
                  Cancel
                </button>
                <button
                  onClick={saveEditing}
                  disabled={saving}
                  className={cn(
                    'px-3 py-1.5 rounded-lg text-xs font-semibold',
                    'bg-gradient-to-r from-[#b3872a] to-[#0f6b4d] text-white',
                    'hover:opacity-90 active:scale-[0.98] disabled:opacity-50',
                    'transition-all duration-150',
                  )}
                >
                  {saving ? 'Saving…' : 'Save'}
                </button>
              </>
            ) : (
              <>
                <button
                  onClick={startEditing}
                  className={cn(
                    'p-1.5 rounded-lg',
                    'hover:bg-[var(--glass)] text-[var(--gold)]',
                    'transition-colors duration-150',
                  )}
                  title="Edit student"
                >
                  <Edit3 size={15} />
                </button>
                <button
                  onClick={onClose}
                  className={cn(
                    'p-1.5 rounded-lg',
                    'hover:bg-[var(--glass)] text-[var(--muted)]',
                    'transition-colors duration-150',
                  )}
                >
                  <X size={16} />
                </button>
              </>
            )}
          </div>
        </div>

        {/* ── Content ─────────────────────────────── */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-6">
          {/* Student Info */}
          {isEditing ? (
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-[11px] font-medium text-[var(--muted)] mb-1 block">First Name</label>
                  <input
                    type="text"
                    value={editFirstName}
                    onChange={(e) => setEditFirstName(e.target.value)}
                    className={cn(
                      'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                      'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                      'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                    )}
                  />
                </div>
                <div>
                  <label className="text-[11px] font-medium text-[var(--muted)] mb-1 block">Last Name</label>
                  <input
                    type="text"
                    value={editLastName}
                    onChange={(e) => setEditLastName(e.target.value)}
                    className={cn(
                      'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                      'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                      'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                    )}
                  />
                </div>
              </div>
              <div>
                <label className="text-[11px] font-medium text-[var(--muted)] mb-1 block">Phone</label>
                <input
                  type="tel"
                  value={editPhone}
                  onChange={(e) => setEditPhone(e.target.value)}
                  placeholder="e.g. 0555123456"
                  className={cn(
                    'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                    'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                    'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                  )}
                />
              </div>
              <div>
                <label className="text-[11px] font-medium text-[var(--muted)] mb-1 block">Parent Phone</label>
                <input
                  type="tel"
                  value={editParentPhone}
                  onChange={(e) => setEditParentPhone(e.target.value)}
                  placeholder="e.g. 0555789012"
                  className={cn(
                    'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                    'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                    'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                  )}
                />
              </div>
              <div>
                <label className="text-[11px] font-medium text-[var(--muted)] mb-1 block">Notes</label>
                <textarea
                  value={editNotes}
                  onChange={(e) => setEditNotes(e.target.value)}
                  rows={3}
                  placeholder="Any notes about this student..."
                  className={cn(
                    'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)] resize-none',
                    'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                    'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                  )}
                />
              </div>
            </div>
          ) : (
            <div className="flex items-start gap-4">
              <div
                className={cn(
                  'w-14 h-14 rounded-2xl flex items-center justify-center shrink-0',
                  'text-lg font-bold',
                )}
                style={{
                  background: 'linear-gradient(135deg, var(--gold-soft), var(--emerald-soft))',
                  color: 'var(--gold)',
                }}
              >
                {getInitials(student.full_name)}
              </div>
              <div className="min-w-0 flex-1">
                <h4 className="text-base font-bold text-[var(--text)] truncate">
                  {student.full_name}
                </h4>
                {student.phone && (
                  <p className="text-sm text-[var(--muted)] flex items-center gap-1.5 mt-1">
                    <Phone size={13} />
                    {formatPhone(student.phone)}
                  </p>
                )}
                <div className="flex items-center gap-2 mt-2">
                  <span
                    className={cn(
                      'inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-medium',
                      getStatusBg(student.status),
                      getStatusColor(student.status),
                    )}
                  >
                    {student.status}
                  </span>
                  {student.plan && (
                    <span className="text-[11px] text-[var(--muted)] flex items-center gap-1">
                      <CreditCard size={10} />
                      {student.plan}
                    </span>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Classes */}
          {student.classes && (
            <Section
              icon={<BookOpen size={14} />}
              title="Enrolled Classes"
            >
              <div className="flex flex-wrap gap-1.5">
                {student.classes.split(',').map((cls, i) => (
                  <span
                    key={i}
                    className={cn(
                      'px-2.5 py-1 rounded-lg text-xs font-medium',
                      'bg-[var(--glass)] border border-[var(--glass-border)]',
                      'text-[var(--text)]',
                    )}
                  >
                    {cls.trim()}
                  </span>
                ))}
              </div>
            </Section>
          )}

          {/* Guardians */}
          <Section
            icon={<Shield size={14} />}
            title="Guardians"
          >
            <div className="space-y-2">
              {student.parent_phone ? (
                <div
                  className={cn(
                    'flex items-center gap-3 px-3 py-2.5 rounded-lg',
                    'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                  )}
                >
                  <div className="w-8 h-8 rounded-full bg-[var(--glass)] flex items-center justify-center">
                    <User size={14} className="text-[var(--muted)]" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-[var(--text)]">Parent / Guardian</p>
                    <p className="text-xs text-[var(--muted)]">{formatPhone(student.parent_phone)}</p>
                  </div>
                  <a
                    href={`tel:${student.parent_phone}`}
                    className="p-1.5 rounded-lg hover:bg-[var(--glass)] transition-colors"
                  >
                    <Phone size={13} className="text-[var(--emerald)]" />
                  </a>
                </div>
              ) : (
                <p className="text-xs text-[var(--muted)] italic">No guardians on file</p>
              )}
            </div>
          </Section>

          {/* T9 Billing summary: Plan / Sessions-month / Renews on / Status */}
          <Section
            icon={<CreditCard size={14} />}
            title="Billing Summary"
          >
            {profileError ? (
              <div className="flex items-center justify-between gap-2">
                <p className="text-xs text-[var(--red)]">{profileError}</p>
                <button
                  type="button"
                  onClick={() => void fetchT9()}
                  className="text-[11px] font-semibold text-[var(--gold)] hover:underline shrink-0"
                >
                  Retry
                </button>
              </div>
            ) : subs.length === 0 ? (
              <p className="text-xs text-[var(--muted)]">No subscription yet — Not set.</p>
            ) : (
              <div className="space-y-2">
                {subs.slice(0, 4).map((s) => (
                  <div
                    key={s.id}
                    className={cn(
                      'px-3 py-2.5 rounded-lg',
                      'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                    )}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <p className="text-xs font-semibold text-[var(--text)] truncate">
                        {s.group_name ?? 'Group'}
                      </p>
                      <span
                        className={cn(
                          'text-[10px] font-semibold px-2 py-0.5 rounded-full shrink-0',
                          (s.status ?? '') === 'ACTIVE'
                            ? 'bg-[var(--emerald-soft)] text-[var(--emerald)]'
                            : 'bg-[var(--red-soft)] text-[var(--red)]',
                        )}
                      >
                        {s.status ?? 'Not set'}
                      </span>
                    </div>
                    <div className="grid grid-cols-3 gap-2 mt-1.5 text-[11px] text-[var(--muted)]">
                      <span title="Plan = subject-level (Credit N)">
                        Plan: {(s.billing_model ?? 'CREDIT_BASED') === 'CREDIT_BASED'
                          ? `Credit ${s.total_credits ?? 'Not set'}`
                          : 'Time · Coming Soon'}
                      </span>
                      <span title="Sessions/month = creditsPerCycle">
                        Sess/mo: {s.total_credits ?? 'Not set'}
                      </span>
                      <span title="Renews on = cycleDeadline">
                        Renews: {s.cycle_deadline ?? 'Not set'}
                      </span>
                    </div>
                  </div>
                ))}
                {(() => {
                  const enrollments: Array<{ class_id: string; class_name?: string | null }> =
                    profile?.enrollments ?? []
                  if (enrollments.length === 0) return null
                  return (
                    <p className="text-[11px] text-[var(--muted)]">
                      Enrolled: {enrollments.map((e) => e.class_name ?? e.class_id).join(', ')}
                    </p>
                  )
                })()}
              </div>
            )}
          </Section>

          {/* Payment Plan */}
          <Section
            icon={<CreditCard size={14} />}
            title="Payment Plan"
          >
            <div className="space-y-3">
              {/* Existing presets */}
              {paymentPresets.length > 0 && (
                <div className="space-y-1.5">
                  {paymentPresets.map((preset) => (
                    <div
                      key={preset.id}
                      className={cn(
                        'flex items-center justify-between px-3 py-2 rounded-lg',
                        'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                      )}
                    >
                      <div className="flex items-center gap-2">
                        <Tag size={12} className="text-[var(--gold)]" />
                        <span className="text-sm font-medium text-[var(--text)]">{preset.name}</span>
                      </div>
                      <span className="text-sm text-[var(--muted)]">{formatCurrency(preset.amount)}</span>
                    </div>
                  ))}
                </div>
              )}

              {/* Blank space / empty state */}
              {paymentPresets.length === 0 && (
                <p className="text-xs text-[var(--muted)] italic">
                  No payment plans yet. Add a custom payment or create a preset.
                </p>
              )}

              {/* Add Payment button */}
              <button
                type="button"
                onClick={() => setShowPaymentModal(true)}
                className={cn(
                  'w-full flex items-center justify-center gap-2 py-2.5 rounded-xl',
                  'text-sm font-medium',
                  'bg-[var(--gold-soft)] text-[var(--gold)] border border-[var(--gold)]/20',
                  'hover:bg-[var(--gold)]/20 active:scale-[0.98]',
                  'transition-all duration-150',
                )}
              >
                <Plus size={14} />
                Add Payment
              </button>
            </div>
          </Section>

          {/* Notes */}
          {!isEditing && (
            <Section icon={<BookOpen size={14} />} title="Notes">
              {student.notes ? (
                <p className="text-sm text-[var(--muted)] leading-relaxed">
                  {student.notes}
                </p>
              ) : (
                <p className="text-xs text-[var(--muted)] italic">No notes</p>
              )}
            </Section>
          )}
        </div>

        {/* ── Footer Actions ──────────────────────── */}
        <div className="px-5 py-4 border-t border-[var(--glass-border)]">
          <div className="flex gap-2">
            {student.phone && (
              <a
                href={`tel:${student.phone}`}
                className={cn(
                  'flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl',
                  'text-sm font-medium',
                  'bg-[var(--emerald)]/10 text-[var(--emerald)]',
                  'hover:bg-[var(--emerald)]/20 active:scale-[0.98]',
                  'transition-all duration-150',
                )}
              >
                <Phone size={15} />
                Call
              </a>
            )}
            {student.phone && (
              <a
                href={`https://wa.me/${student.phone.replace(/[^0-9]/g, '')}`}
                target="_blank"
                rel="noopener noreferrer"
                className={cn(
                  'flex-1 flex items-center justify-center gap-2 py-2.5 rounded-xl',
                  'text-sm font-medium',
                  'bg-[var(--emerald-soft)] text-[var(--emerald)]',
                  'hover:bg-[var(--emerald)]/20 active:scale-[0.98]',
                  'transition-all duration-150',
                )}
              >
                <MessageCircle size={15} />
                Message
              </a>
            )}
          </div>
        </div>
      </div>

      {/* Payment Modal */}
      {showPaymentModal && (
        <PaymentModal
          studentId={student.id}
          presets={paymentPresets}
          onAddPreset={(preset) => setPaymentPresets((prev) => [...prev, preset])}
          onPaymentRecorded={fetchBillingRecords}
          onClose={() => setShowPaymentModal(false)}
        />
      )}
    </div>
  )
}

// ============================================
// Section (internal)
// ============================================

function Section({
  icon,
  title,
  children,
}: {
  icon: React.ReactNode
  title: string
  children: React.ReactNode
}) {
  return (
    <div>
      <div className="flex items-center gap-2 mb-2.5">
        <span className="text-[var(--gold)]">{icon}</span>
        <h5 className="text-xs font-semibold text-[var(--muted)] uppercase tracking-wider">
          {title}
        </h5>
      </div>
      {children}
    </div>
  )
}

// ============================================
// Payment Modal (internal)
// ============================================

function PaymentModal({
  studentId,
  presets,
  onAddPreset,
  onPaymentRecorded,
  onClose,
}: {
  studentId: string
  presets: PaymentPreset[]
  onAddPreset: (preset: PaymentPreset) => void
  onPaymentRecorded: () => void
  onClose: () => void
}) {
  const [mode, setMode] = useState<'choose' | 'custom' | 'preset'>('choose')
  const [customAmount, setCustomAmount] = useState('')
  const [presetName, setPresetName] = useState('')
  const [presetAmount, setPresetAmount] = useState('')
  const [loading, setLoading] = useState(false)

  const handleAddCustom = async () => {
    if (!customAmount) return
    setLoading(true)
    try {
      await api.post('/billing/record-payment', {
        student_id: studentId,
        amount_da: Number(customAmount),
        payment_method: 'cash',
        notes: 'Custom payment from student profile',
      })
      toast.success('Payment recorded', `Amount: ${formatCurrency(Number(customAmount))}`)
      onPaymentRecorded()
      onClose()
    } catch {
      toast.error('Payment failed', 'Could not record the payment. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  const handleAddPreset = async () => {
    if (!presetName.trim() || !presetAmount) return
    setLoading(true)
    try {
      await api.post('/billing/plans', {
        name: presetName.trim(),
        amount_da: Number(presetAmount),
        duration_days: 30,
      })
      toast.success('Preset created', `"${presetName.trim()}" payment plan saved.`)
      onAddPreset({
        id: Date.now().toString(),
        name: presetName.trim(),
        amount: Number(presetAmount),
      })
      onClose()
    } catch {
      toast.error('Preset failed', 'Could not create payment plan. Please try again.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-[60] flex items-center justify-center"
      style={{ background: 'rgba(10,10,10,.6)', backdropFilter: 'blur(8px)' }}
      onClick={(e) => { if (e.target === e.currentTarget) onClose() }}
    >
      <div
        className={cn(
          'w-full max-w-sm mx-4 p-5 rounded-2xl',
          'bg-[var(--card-bg)] border border-[var(--glass-border)]',
          'shadow-2xl animate-fade-in',
        )}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-base font-bold text-[var(--text)]" style={{ fontFamily: 'var(--font-heading)' }}>
            Add Payment
          </h3>
          <button onClick={onClose} className="p-1 rounded-lg text-[var(--muted)] hover:bg-[var(--glass)]">
            <X size={14} />
          </button>
        </div>

        {/* Choose mode */}
        {mode === 'choose' && (
          <div className="space-y-2">
            <button
              type="button"
              onClick={() => setMode('custom')}
              className={cn(
                'w-full flex items-center gap-3 px-4 py-3 rounded-xl',
                'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                'hover:border-[var(--gold)]/30 transition-all text-left',
              )}
            >
              <CreditCard size={16} className="text-[var(--gold)]" />
              <div>
                <p className="text-sm font-medium text-[var(--text)]">Custom Payment</p>
                <p className="text-xs text-[var(--muted)]">One-time payment with custom amount</p>
              </div>
            </button>
            <button
              type="button"
              onClick={() => setMode('preset')}
              className={cn(
                'w-full flex items-center gap-3 px-4 py-3 rounded-xl',
                'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                'hover:border-[var(--emerald)]/30 transition-all text-left',
              )}
            >
              <Tag size={16} className="text-[var(--emerald)]" />
              <div>
                <p className="text-sm font-medium text-[var(--text)]">Create Preset</p>
                <p className="text-xs text-[var(--muted)]">Save a reusable payment plan</p>
              </div>
            </button>
          </div>
        )}

        {/* Custom payment */}
        {mode === 'custom' && (
          <div className="space-y-3">
            <div>
              <label className="text-xs font-medium text-[var(--muted)] mb-1 block">Amount (DA)</label>
              <input
                type="number"
                value={customAmount}
                onChange={(e) => setCustomAmount(e.target.value)}
                placeholder="e.g. 3500"
                className={cn(
                  'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                  'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                  'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                )}
              />
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setMode('choose')}
                className="flex-1 py-2 rounded-xl text-sm font-medium bg-[var(--input-bg)] text-[var(--muted)] border border-[var(--glass-border)]"
              >
                Back
              </button>
              <button
                type="button"
                onClick={handleAddCustom}
                disabled={!customAmount || loading}
                className="flex-1 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-[#b3872a] to-[#0f6b4d] disabled:opacity-40"
              >
                {loading ? 'Saving…' : 'Add'}
              </button>
            </div>
          </div>
        )}

        {/* Create preset */}
        {mode === 'preset' && (
          <div className="space-y-3">
            <div>
              <label className="text-xs font-medium text-[var(--muted)] mb-1 block">Preset Name</label>
              <input
                type="text"
                value={presetName}
                onChange={(e) => setPresetName(e.target.value)}
                placeholder="e.g. Monthly Plan"
                className={cn(
                  'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                  'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                  'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                )}
              />
            </div>
            <div>
              <label className="text-xs font-medium text-[var(--muted)] mb-1 block">Amount (DA)</label>
              <input
                type="number"
                value={presetAmount}
                onChange={(e) => setPresetAmount(e.target.value)}
                placeholder="e.g. 3500"
                className={cn(
                  'w-full px-3 py-2 rounded-xl text-sm text-[var(--text)]',
                  'bg-[var(--input-bg)] border border-[var(--glass-border)]',
                  'outline-none focus:ring-2 focus:ring-[var(--gold)]/30',
                )}
              />
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => setMode('choose')}
                className="flex-1 py-2 rounded-xl text-sm font-medium bg-[var(--input-bg)] text-[var(--muted)] border border-[var(--glass-border)]"
              >
                Back
              </button>
              <button
                type="button"
                onClick={handleAddPreset}
                disabled={!presetName.trim() || !presetAmount || loading}
                className="flex-1 py-2 rounded-xl text-sm font-semibold text-white bg-gradient-to-r from-[#b3872a] to-[#0f6b4d] disabled:opacity-40"
              >
                {loading ? 'Saving…' : 'Save Preset'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
